// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { BridgeUSDC } from "./BridgeUSDC.sol";

/**
 * @title BridgeReceiver
 * @notice Receives lock fulfillment from the relayer and mints USDC.k on Story Aeneid (Base → Story).
 *         Users can lock back USDC.k to receive USDC on Base Sepolia (Story → Base). Only attester can fulfillLock/release.
 * @author Asura aka Angel of Indian Krump
 * @custom:website https://asura.lovable.app/
 * @custom:initiative StreetKode Fam Initiative
 * @custom:credits StreetKode Fam: Asura, Hectik, Kronos, Jo
 */
contract BridgeReceiver {
    BridgeUSDC public immutable bridgeUsdc;
    address public attester;

    /// @notice Replay protection for fulfillLock (Base → Story)
    mapping(uint64 sourceChainId => mapping(uint256 nonce => bool)) public usedNonce;
    /// @notice Replay protection for lockBack (Story → Base)
    uint256 public nonceBack;
    mapping(uint256 nonce => bool) public usedNonceBack;

    event FulfillLock(
        uint64 indexed sourceChainId,
        uint256 indexed nonce,
        address indexed recipient,
        uint256 amount
    );
    /// @notice Emitted when user locks USDC.k to bridge back to Base Sepolia
    event LockRequestBack(
        uint64 indexed destinationChainId,
        address indexed sender,
        address indexed destinationRecipient,
        uint256 amount,
        uint256 nonce
    );
    event AttesterSet(address indexed previousAttester, address indexed newAttester);

    error OnlyAttester();
    error AlreadyFulfilled();
    error ZeroRecipient();
    error ZeroAmount();

    modifier onlyAttester() {
        if (msg.sender != attester) revert OnlyAttester();
        _;
    }

    constructor(address _bridgeUsdc, address _attester) {
        require(_bridgeUsdc != address(0), "BridgeReceiver: zero bridgeUsdc");
        require(_attester != address(0), "BridgeReceiver: zero attester");
        bridgeUsdc = BridgeUSDC(_bridgeUsdc);
        attester = _attester;
    }

    /**
     * @notice Fulfill a lock from the source chain: mint BridgeUSDC to the recipient.
     * @param sourceChainId Chain ID where the lock happened (e.g. 84532 for Base Sepolia).
     * @param nonce Nonce from the LockRequest event.
     * @param recipient Address to credit on this chain (Story Aeneid).
     * @param amount Amount to mint (6 decimals).
     */
    function fulfillLock(
        uint64 sourceChainId,
        uint256 nonce,
        address recipient,
        uint256 amount
    ) external onlyAttester {
        if (recipient == address(0)) revert ZeroRecipient();
        if (amount == 0) revert ZeroAmount();
        if (usedNonce[sourceChainId][nonce]) revert AlreadyFulfilled();

        usedNonce[sourceChainId][nonce] = true;
        bridgeUsdc.mint(recipient, amount);

        emit FulfillLock(sourceChainId, nonce, recipient, amount);
    }

    /**
     * @notice Lock USDC.k to bridge back to Base Sepolia. User transfers USDC.k to this contract; relayer releases USDC on Base.
     * @param amount Amount to lock (6 decimals).
     * @param destinationRecipient Address to credit on Base Sepolia.
     */
    function lockBack(uint256 amount, address destinationRecipient) external {
        if (amount == 0) revert ZeroAmount();
        if (destinationRecipient == address(0)) revert ZeroRecipient();

        bridgeUsdc.transferFrom(msg.sender, address(this), amount);
        uint256 currentNonce = nonceBack;
        nonceBack = currentNonce + 1;

        // Base Sepolia chain ID for relayer to release there
        emit LockRequestBack(84532, msg.sender, destinationRecipient, amount, currentNonce);
    }

    /// @notice Change the attester (e.g. to a multisig). In PoC, only deployer can do this; add Ownable if needed.
    function setAttester(address _attester) external {
        if (msg.sender != attester) revert OnlyAttester();
        require(_attester != address(0), "BridgeReceiver: zero attester");
        address old = attester;
        attester = _attester;
        emit AttesterSet(old, _attester);
    }
}

contracts/bridge/BridgeUSDC.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title BridgeUSDC
 * @notice ERC20 "USDC.k" (USDC Krump) minted on Story Aeneid when the custom bridge fulfills a lock from Base Sepolia.
 *         Only the BridgeReceiver can mint. Implements EIP-3009 for x402/OpenClaw agent payments on EVVM 1140.
 * @author Asura aka Angel of Indian Krump
 * @custom:website https://asura.lovable.app/
 * @custom:initiative StreetKode Fam Initiative
 * @custom:credits StreetKode Fam: Asura, Hectik, Kronos, Jo
 * @custom:security This contract implements EIP-3009 for gasless transfers via signed authorizations.
 */
contract BridgeUSDC is ERC20, Ownable {
    address public minter;

    uint8 private constant DECIMALS = 6;
    string private constant EIP712_NAME = "USDC Krump";

    bytes32 public constant TRANSFER_WITH_AUTHORIZATION_TYPEHASH = keccak256(
        "TransferWithAuthorization(address from,address to,uint256 amount,uint256 validAfter,uint256 validBefore,bytes32 nonce)"
    );
    bytes32 public constant DOMAIN_TYPEHASH = keccak256(
        "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
    );

    mapping(bytes32 => bool) public usedNonces;

    event MinterSet(address indexed previousMinter, address indexed newMinter);
    event AuthorizationUsed(address indexed from, address indexed to, bytes32 indexed nonce);

    error OnlyMinter();
    error ZeroMinter();

    constructor() ERC20("USDC Krump", "USDC.k") {
        // Owner can set minter after BridgeReceiver is deployed
    }

    function decimals() public pure override returns (uint8) {
        return DECIMALS;
    }

    /// @notice Set the only address allowed to mint (BridgeReceiver). Call once after deploying BridgeReceiver.
    function setMinter(address _minter) external onlyOwner {
        if (_minter == address(0)) revert ZeroMinter();
        address old = minter;
        minter = _minter;
        emit MinterSet(old, _minter);
    }

    /// @notice Mint bridged USDC to recipient. Only callable by minter (BridgeReceiver).
    function mint(address to, uint256 amount) external {
        if (msg.sender != minter) revert OnlyMinter();
        _mint(to, amount);
    }

    /// @notice EIP-3009: Transfer with Authorization (x402 protocol). Same interface as USDCDanceOFT for EVVMPaymentAdapter.
    function transferWithAuthorization(
        address from,
        address to,
        uint256 amount,
        uint256 validAfter,
        uint256 validBefore,
        bytes32 nonce,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external {
        require(block.timestamp > validAfter, "BridgeUSDC: auth not yet valid");
        require(block.timestamp < validBefore, "BridgeUSDC: auth expired");
        require(!usedNonces[nonce], "BridgeUSDC: nonce used");

        bytes32 structHash = keccak256(
            abi.encode(
                TRANSFER_WITH_AUTHORIZATION_TYPEHASH,
                from,
                to,
                amount,
                validAfter,
                validBefore,
                nonce
            )
        );
        bytes32 domainSeparator = keccak256(
            abi.encode(
                DOMAIN_TYPEHASH,
                keccak256(bytes(EIP712_NAME)),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", domainSeparator, structHash));
        address signer = ecrecover(digest, v, r, s);
        require(signer == from, "BridgeUSDC: invalid signature");

        usedNonces[nonce] = true;
        _transfer(from, to, amount);
        emit AuthorizationUsed(from, to, nonce);
    }

    function getDomainSeparator() external view returns (bytes32) {
        return keccak256(
            abi.encode(
                DOMAIN_TYPEHASH,
                keccak256(bytes(EIP712_NAME)),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );
    }

    function isNonceUsed(bytes32 nonce) external view returns (bool) {
        return usedNonces[nonce];
    }
}

contracts/bridge/BridgeVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title BridgeVault
 * @notice Holds locked USDC on Base Sepolia. Users lock USDC → relayer mints USDC.k on Story Aeneid.
 *         Users lock USDC.k on Story Aeneid → relayer calls release here to send USDC to recipient.
 * @dev PoC: trusted relayer/attester; replay protection via nonce.
 * @author Asura aka Angel of Indian Krump
 * @custom:website https://asura.lovable.app/
 * @custom:initiative StreetKode Fam Initiative
 * @custom:credits StreetKode Fam: Asura, Hectik, Kronos, Jo
 */
contract BridgeVault {
    using SafeERC20 for IERC20;

    IERC20 public immutable token;
    uint64 public immutable sourceChainId;
    address public attester;
    uint256 public nonce;

    /// @notice Replay protection for release (Story → Base)
    mapping(uint64 sourceChainId => mapping(uint256 nonce => bool)) public usedReleaseNonce;

    event LockRequest(
        uint64 indexed sourceChainId,
        address indexed sender,
        address indexed destinationRecipient,
        uint256 amount,
        uint256 nonce
    );
    event Release(
        uint64 indexed sourceChainId,
        uint256 indexed nonce,
        address indexed recipient,
        uint256 amount
    );
    event AttesterSet(address indexed previousAttester, address indexed newAttester);

    error ZeroAmount();
    error ZeroRecipient();
    error OnlyAttester();
    error AlreadyReleased();

    modifier onlyAttester() {
        if (msg.sender != attester) revert OnlyAttester();
        _;
    }

    constructor(address _token, uint64 _sourceChainId, address _attester) {
        require(_token != address(0), "BridgeVault: zero token");
        require(_attester != address(0), "BridgeVault: zero attester");
        token = IERC20(_token);
        sourceChainId = _sourceChainId;
        attester = _attester;
    }

    /**
     * @notice Lock tokens and emit a request for the relayer to fulfill on the destination chain.
     * @param amount Amount to lock (same decimals as the token, e.g. 6 for USDC).
     * @param destinationRecipient Address to credit on the destination chain (Story Aeneid).
     */
    function lock(uint256 amount, address destinationRecipient) external {
        if (amount == 0) revert ZeroAmount();
        if (destinationRecipient == address(0)) revert ZeroRecipient();

        token.safeTransferFrom(msg.sender, address(this), amount);
        uint256 currentNonce = nonce;
        nonce = currentNonce + 1;

        emit LockRequest(
            sourceChainId,
            msg.sender,
            destinationRecipient,
            amount,
            currentNonce
        );
    }

    /**
     * @notice Release USDC to recipient when relayer fulfills a LockRequestBack from Story Aeneid.
     * @param recipient Address to credit on this chain (Base Sepolia).
     * @param amount Amount to transfer (6 decimals).
     * @param sourceChainId Chain ID where lockBack happened (1315 for Story Aeneid).
     * @param nonce Nonce from the LockRequestBack event.
     */
    function release(
        address recipient,
        uint256 amount,
        uint64 sourceChainId,
        uint256 nonce
    ) external onlyAttester {
        if (recipient == address(0)) revert ZeroRecipient();
        if (amount == 0) revert ZeroAmount();
        if (usedReleaseNonce[sourceChainId][nonce]) revert AlreadyReleased();

        usedReleaseNonce[sourceChainId][nonce] = true;
        token.safeTransfer(recipient, amount);

        emit Release(sourceChainId, nonce, recipient, amount);
    }

    function setAttester(address _attester) external onlyAttester {
        require(_attester != address(0), "BridgeVault: zero attester");
        address old = attester;
        attester = _attester;
        emit AttesterSet(old, _attester);
    }
}

contracts/EVVMPaymentAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title EVVM Payment Adapter
 * @notice Bridges x402 (EIP-3009) payments with EVVM Core for autonomous agent interactions
 * @dev Allows OpenClaw agents to pay with USDC.d via x402 protocol on EVVM.
 *      Enables seamless autonomous payments from OpenClaw agents to human owners via EVVM.
 * 
 * Integration Flow:
 * 1. Agent signs EIP-3009 authorization (x402 protocol)
 * 2. Adapter executes transferWithAuthorization on USDCDanceOFT
 * 3. Adapter calls EVVM Core's pay function to route payment
 * 4. Human owner receives USDC.d autonomously via EVVM
 * 
 * @author Asura aka Angel of Indian Krump
 * @custom:website https://asura.lovable.app/
 * @custom:initiative StreetKode Fam Initiative
 * @custom:credits StreetKode Fam: Asura, Hectik, Kronos, Jo
 * @custom:security This contract integrates with EVVM Core for secure, autonomous payment routing.
 */
import "./USDCDanceOFT.sol";

contract EVVMPaymentAdapter {
    /// @notice Reference to the USDCDanceOFT token contract
    USDCDanceOFT public immutable usdcDance;

    /// @notice Reference to the EVVM Core contract
    address public immutable evvmCore;

    /// @notice EVVM instance ID (1140 for Story Aeneid)
    uint256 public immutable evvmId;

    /// @notice Owner address that can update adapter settings
    address public owner;

    /// @notice Tracks processed x402 payments to prevent replay attacks
    mapping(bytes32 => bool) public processedPayments;

    /// @notice Stores EVVM payment information by receipt ID
    mapping(string => EVVMPaymentInfo) public evvmPayments;

    /// @notice EVVM payment information structure
    struct EVVMPaymentInfo {
        address from;
        address to;
        uint256 amount;
        string receiptId;
        uint256 timestamp;
        bool exists;
    }

    /// @notice Emitted when an x402 payment is processed through EVVM
    event EVVMPaymentProcessed(
        address indexed from,
        address indexed to,
        uint256 amount,
        string receiptId,
        bytes32 x402Nonce
    );

    /// @notice Emitted when the owner address is updated
    event OwnerUpdated(address indexed oldOwner, address indexed newOwner);

    /**
     * @notice Initializes the EVVM Payment Adapter contract
     * @param _usdcDance The address of the USDCDanceOFT token contract
     * @param _evvmCore The address of the EVVM Core contract
     * @param _evvmId The EVVM instance ID (1140 for Story Aeneid)
     * @param _owner The owner address that can update adapter settings
     * @dev Sets up the adapter to bridge x402 payments with EVVM Core for autonomous agent payments
     */
    constructor(
        address _usdcDance,
        address _evvmCore,
        uint256 _evvmId,
        address _owner
    ) {
        require(_usdcDance != address(0), "EVVMPaymentAdapter: Invalid USDC.d address");
        require(_evvmCore != address(0), "EVVMPaymentAdapter: Invalid EVVM Core address");
        require(_owner != address(0), "EVVMPaymentAdapter: Invalid owner address");

        usdcDance = USDCDanceOFT(_usdcDance);
        evvmCore = _evvmCore;
        evvmId = _evvmId;
        owner = _owner;
    }

    /**
     * @notice Process x402 payment and route through EVVM Core
     * @dev Accepts EIP-3009 authorization, executes transfer, then routes via EVVM.
     *      This enables OpenClaw agents to make autonomous payments via x402 protocol.
     * @param from The address authorizing the payment (must match signature)
     * @param to The recipient address
     * @param toIdentity The EVVM identity string for the recipient
     * @param amount The payment amount in USDC.d (6 decimals)
     * @param validAfter Timestamp after which authorization is valid
     * @param validBefore Timestamp before which authorization expires
     * @param nonce Unique nonce to prevent replay attacks
     * @param v Recovery byte of the ECDSA signature
     * @param r R value of the ECDSA signature
     * @param s S value of the ECDSA signature
     * @param receiptId Receipt ID for payment tracking
     * @param evvmNonce EVVM nonce for the payment transaction
     * @param isAsyncExec Whether to execute asynchronously on EVVM
     * @param evvmSignature EVVM signature for the payment
     */
    function payViaEVVMWithX402(
        address from,
        address to,
        string memory toIdentity,
        uint256 amount,
        uint256 validAfter,
        uint256 validBefore,
        bytes32 nonce,
        uint8 v,
        bytes32 r,
        bytes32 s,
        string memory receiptId,
        uint256 evvmNonce,
        bool isAsyncExec,
        bytes memory evvmSignature
    ) external {
        require(!processedPayments[nonce], "EVVMPaymentAdapter: Payment already processed");

        // Step 1: Execute x402 payment (EIP-3009 transferWithAuthorization)
        usdcDance.transferWithAuthorization(
            from,
            address(this),
            amount,
            validAfter,
            validBefore,
            nonce,
            v,
            r,
            s
        );

        // Step 2: Approve EVVM Core to spend USDC.d
        usdcDance.approve(evvmCore, amount);

        // Step 3: Route payment through EVVM Core
        (bool success, ) = evvmCore.call(
            abi.encodeWithSignature(
                "pay(address,address,string,address,uint256,uint256,address,uint256,bool,bytes)",
                from,
                to,
                toIdentity,
                address(usdcDance),
                amount,
                0,
                address(0),
                evvmNonce,
                isAsyncExec,
                evvmSignature
            )
        );

        require(success, "EVVMPaymentAdapter: EVVM payment failed");

        // Step 4: Record payment
        processedPayments[nonce] = true;
        evvmPayments[receiptId] = EVVMPaymentInfo({
            from: from,
            to: to,
            amount: amount,
            receiptId: receiptId,
            timestamp: block.timestamp,
            exists: true
        });

        emit EVVMPaymentProcessed(from, to, amount, receiptId, nonce);
    }

    /**
     * @notice Get EVVM payment information by receipt ID
     * @param receiptId The receipt ID to look up
     * @return from The address that made the payment
     * @return to The recipient address
     * @return amount The payment amount
     * @return timestamp When the payment was processed
     * @return exists Whether the payment exists
     */
    function getEVVMPaymentInfo(string memory receiptId)
        external
        view
        returns (
            address from,
            address to,
            uint256 amount,
            uint256 timestamp,
            bool exists
        )
    {
        EVVMPaymentInfo memory payment = evvmPayments[receiptId];
        return (payment.from, payment.to, payment.amount, payment.timestamp, payment.exists);
    }

    /**
     * @notice Update the owner address
     * @param _newOwner The new owner address
     * @dev Only the current owner can call this function
     */
    function setOwner(address _newOwner) external {
        require(msg.sender == owner, "EVVMPaymentAdapter: Only owner");
        require(_newOwner != address(0), "EVVMPaymentAdapter: Invalid owner");
        address oldOwner = owner;
        owner = _newOwner;
        emit OwnerUpdated(oldOwner, _newOwner);
    }
}

